package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_2 : Integer;
    attribute accumulatedMs : Integer := 0;
    attribute led0State : Boolean := false;
    attribute led1State : Boolean := false;
    perform action tick {
      first start;
      then assign accumulatedMs := accumulatedMs + io_2;
      then if ((accumulatedMs) >= (1000)) {
        first start;
        then assign accumulatedMs := accumulatedMs - 1000;
        then assign led0State := not led0State;
        then assign led1State := not led1State;
      }
    }
    out attribute io_0 : Boolean = led0State;
    out attribute io_1 : Boolean = led1State;
  }
  part system : Controller;
}
